create table if not exists public.products(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),name text not null,price numeric not null default 0,image text not null default '',description text not null default '');
create table if not exists public.videos(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),title text not null,url text not null,description text not null default '');
create table if not exists public.orders(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),customer_name text not null,phone text not null,address text not null default '',items jsonb not null default '[]'::jsonb,total numeric not null default 0,status text not null default 'new');
alter table public.products enable row level security;alter table public.videos enable row level security;alter table public.orders enable row level security;
drop policy if exists "public read products" on public.products;create policy "public read products" on public.products for select to anon,authenticated using(true);
drop policy if exists "public read videos" on public.videos;create policy "public read videos" on public.videos for select to anon,authenticated using(true);